diff --git a/src/main/java/hotel/reports/RatePlansReport.java b/src/main/java/hotel/reports/RatePlansReport.java
new file mode 100644
index 0000000..2118f54
--- /dev/null
+++ b/src/main/java/hotel/reports/RatePlansReport.java
@@ -0,0 +1,84 @@
+package hotel.reports;
+
+import hotel.reservations.RatePlan;
+import hotel.reservations.Reservation;
+import hotel.reservations.ReservationStore;
+import java.math.BigDecimal;
+import java.time.YearMonth;
+import java.util.ArrayList;
+import java.util.List;
+
+/**
+ * Revenue grouped by rate plan for reservations starting in a given month.
+ */
+public final class RatePlansReport extends Report<RatePlansReport.RatePlanRow> {
+
+    record RatePlanRow(RatePlan ratePlan, int reservations, BigDecimal amount) {}
+
+    private final ReservationStore store;
+
+    public RatePlansReport(ReservationStore store) {
+        this.store = store;
+    }
+
+    public String generate(YearMonth month) {
+        return generateCsv(month);
+    }
+
+    @Override
+    protected String reportName() {
+        return "rate-plans";
+    }
+
+    @Override
+    protected List<RatePlanRow> collectData(Object period) {
+        YearMonth month = (YearMonth) period;
+
+        // Count reservations and sum amounts for each rate plan
+        int standardCount = 0;
+        BigDecimal standardAmount = BigDecimal.ZERO.setScale(2);
+        int nonRefundableCount = 0;
+        BigDecimal nonRefundableAmount = BigDecimal.ZERO.setScale(2);
+
+        for (Reservation reservation : store.all()) {
+            boolean keptMoney = reservation.amountKept().signum() > 0;
+            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
+            if (keptMoney && startsInMonth) {
+                if (reservation.ratePlan() == RatePlan.STANDARD) {
+                    standardCount++;
+                    standardAmount = standardAmount.add(reservation.amountKept());
+                } else if (reservation.ratePlan() == RatePlan.NON_REFUNDABLE) {
+                    nonRefundableCount++;
+                    nonRefundableAmount = nonRefundableAmount.add(reservation.amountKept());
+                }
+            }
+        }
+
+        // Always include both plans, even if one has no reservations
+        List<RatePlanRow> rows = new ArrayList<>();
+        rows.add(new RatePlanRow(RatePlan.STANDARD, standardCount, standardAmount));
+        rows.add(new RatePlanRow(RatePlan.NON_REFUNDABLE, nonRefundableCount, nonRefundableAmount));
+        return rows;
+    }
+
+    @Override
+    protected String headerLine() {
+        return "rate_plan,reservations,amount\n";
+    }
+
+    @Override
+    protected String dataLine(RatePlanRow row) {
+        return row.ratePlan + "," + row.reservations + "," + row.amount.toPlainString() + "\n";
+    }
+
+    @Override
+    protected String totalLine(List<RatePlanRow> data) {
+        int totalReservations = 0;
+        BigDecimal totalAmount = BigDecimal.ZERO.setScale(2);
+        for (RatePlanRow row : data) {
+            totalReservations += row.reservations;
+            totalAmount = totalAmount.add(row.amount);
+        }
+        return "total," + totalReservations + "," + totalAmount.toPlainString() + "\n";
+    }
+}
diff --git a/src/main/java/hotel/reports/Report.java b/src/main/java/hotel/reports/Report.java
new file mode 100644
index 0000000..366101b
--- /dev/null
+++ b/src/main/java/hotel/reports/Report.java
@@ -0,0 +1,45 @@
+package hotel.reports;
+
+import java.util.List;
+
+/**
+ * Base class for all CSV reports. The structure is fixed: title line, header, data rows, total line.
+ * Each concrete report defines its own name, columns, data and total.
+ */
+public abstract class Report<T> {
+
+    /**
+     * Generates the full CSV report with title, header, data rows and total.
+     */
+    public final String generateCsv(Object period) {
+        List<T> data = collectData(period);
+
+        StringBuilder csv = new StringBuilder();
+        csv.append(titleLine(period));
+        csv.append(headerLine());
+        for (T row : data) {
+            csv.append(dataLine(row));
+        }
+        csv.append(totalLine(data));
+        return csv.toString();
+    }
+
+    /** The name of this report for the title line (e.g., "occupancy", "revenue"). */
+    protected abstract String reportName();
+
+    /** The data rows to include in this report for the given period. */
+    protected abstract List<T> collectData(Object period);
+
+    /** The CSV header line (e.g., "room,type,reservation\n"). */
+    protected abstract String headerLine();
+
+    /** One CSV data line for the given row (e.g., "101,STANDARD,5\n"). */
+    protected abstract String dataLine(T row);
+
+    /** The total line at the end of the report (e.g., "total,10\n"). */
+    protected abstract String totalLine(List<T> data);
+
+    private String titleLine(Object period) {
+        return "Pousada Maré Alta," + reportName() + "," + period + "\n";
+    }
+}
