 61	    record RatePlanRow(RatePlan ratePlan, int reservations, BigDecimal amount) {}
 62	
 63	    private final ReservationStore store;
 64	
 65	    public RatePlansReport(ReservationStore store) {
 66	        this.store = store;
 67	    }
