 78	    @Override
 79	    protected List<RatePlanRow> collectData(Object period) {
 80	        YearMonth month = (YearMonth) period;
 81	
 82	        // Count reservations and sum amounts for each rate plan
 83	        int standardCount = 0;
 84	        BigDecimal standardAmount = BigDecimal.ZERO.setScale(2);
 85	        int nonRefundableCount = 0;
 86	        BigDecimal nonRefundableAmount = BigDecimal.ZERO.setScale(2);
 87	
 88	        for (Reservation reservation : store.all()) {
 89	            boolean keptMoney = reservation.amountKept().signum() > 0;
 90	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
 91	            if (keptMoney && startsInMonth) {
 92	                if (reservation.ratePlan() == RatePlan.STANDARD) {
 93	                    standardCount++;
 94	                    standardAmount = standardAmount.add(reservation.amountKept());
 95	                } else if (reservation.ratePlan() == RatePlan.NON_REFUNDABLE) {
 96	                    nonRefundableCount++;
 97	                    nonRefundableAmount = nonRefundableAmount.add(reservation.amountKept());
 98	                }
 99	            }
100	        }
101	
102	        // Always include both plans, even if one has no reservations
103	        List<RatePlanRow> rows = new ArrayList<>();
104	        rows.add(new RatePlanRow(RatePlan.STANDARD, standardCount, standardAmount));
105	        rows.add(new RatePlanRow(RatePlan.NON_REFUNDABLE, nonRefundableCount, nonRefundableAmount));
106	        return rows;
107	    }
108	
109	    @Override
110	    protected String headerLine() {
111	        return "rate_plan,reservations,amount\n";
112	    }
