120	    protected String totalLine(List<RatePlanRow> data) {
121	        int totalReservations = 0;
122	        BigDecimal totalAmount = BigDecimal.ZERO.setScale(2);
123	        for (RatePlanRow row : data) {
124	            totalReservations += row.reservations;
125	            totalAmount = totalAmount.add(row.amount);
126	        }
127	        return "total," + totalReservations + "," + totalAmount.toPlainString() + "\n";
128	    }
129	}
